//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn text_split_native_descriptor_detached_owners_kinds_units_and_fresh_author_state(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var d=Object.getOwnPropertyDescriptor(Text.prototype,'splitText'),split=d.value;if(split.name!=='splitText'||split.length!==1||!d.enumerable||!d.writable||!d.configurable||Object.hasOwn(CDATASection.prototype,'splitText'))throw 'canonical Text method descriptor';var xml=document.implementation.createDocument(null,''),generic=new Document(),html=document.implementation.createHTMLDocument('owner'),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument;for(var owner of [document,html,xml,generic,template]){var nodes=[owner.createTextNode('A\ud83d\ude00B\ud800C')];if(owner===xml||owner===generic||owner===template)nodes.push(owner.createCDATASection('A\ud83d\ude00B\ud800C'));for(var node of nodes){var kind=node.nodeType,binding={held:node};node.bindingState=binding;var tail=split.call(node,2);if(tail===node||node.nodeType!==kind||node.data!=='A\ud83d'||tail.nodeType!==3||tail instanceof CDATASection||!(tail instanceof Text)||tail.data!=='\ude00B\ud800C'||node.ownerDocument!==owner||tail.ownerDocument!==owner||node.parentNode!==null||tail.parentNode!==null||node.bindingState!==binding||tail.bindingState!==undefined||node.wholeText!==node.data||tail.wholeText!==tail.data)throw 'genuine detached split exact prefix tail kinds owners and new author state';}}var text=document.createTextNode('held'),end=text.splitText(4);if(text.data!=='held'||end.data!==''||end.parentNode!==null)throw 'split at end creates empty Text';var whole=text.splitText(0);if(text.data!==''||whole.data!=='held')throw 'split at zero';for(var bad of [document,document.body,document.createAttribute('x'),document.createComment('x'),document.createProcessingInstruction('x','data'),{},Text.prototype,null]){var calls=0,caught=false;try{split.call(bad,{valueOf:function(){calls++;return 0;}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'Text-only brand before conversion';}
"#);
}
#[test]
fn text_split_parented_sources_keep_order_views_owners_clones_and_record_order(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var xml=document.implementation.createDocument(null,''),generic=new Document(),html=document.implementation.createHTMLDocument('owner'),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument;for(var owner of [document,html,xml,generic,template]){var parent=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),text=owner.createTextNode('abcdef'),after=owner.createComment('after'),copy=text.cloneNode(false);parent.appendChild(text);parent.appendChild(after);var list=parent.childNodes,watch=new MutationObserver(function(){});watch.observe(parent,{subtree:true,childList:true,characterData:true,characterDataOldValue:true});var tail=text.splitText(2),records=watch.takeRecords();if(text.data!=='ab'||tail.data!=='cdef'||tail.ownerDocument!==owner||tail.parentNode!==parent||text.parentNode!==parent||parent.childNodes!==list||list.length!==3||list[0]!==text||list[1]!==tail||list[2]!==after||text.nextSibling!==tail||tail.previousSibling!==text||tail.nextSibling!==after||copy.data!=='abcdef'||text.wholeText!=='abcdef'||tail.wholeText!=='abcdef')throw 'actual parent order owner view and immutable clone';if(records.length!==2||records[0].type!=='childList'||records[0].target!==parent||records[0].addedNodes.length!==1||records[0].addedNodes[0]!==tail||records[0].removedNodes.length||records[0].previousSibling!==text||records[0].nextSibling!==after||records[1].type!=='characterData'||records[1].target!==text||records[1].oldValue!=='abcdef')throw 'insertion record precedes original character-data record';watch.disconnect();}");
}
#[test]
fn text_split_live_ranges_move_tail_and_parent_gap_but_detached_points_collapse(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var parent=document.createElement('span'),text=document.createTextNode('abcdef'),after=document.createComment('after');parent.appendChild(text);parent.appendChild(after);var crossing=document.createRange(),boundary=document.createRange(),gap=document.createRange();crossing.setStart(text,1);crossing.setEnd(text,5);boundary.setStart(text,2);boundary.collapse(true);gap.setStart(parent,1);gap.setEnd(parent,2);var tail=text.splitText(2);if(crossing.startContainer!==text||crossing.startOffset!==1||crossing.endContainer!==tail||crossing.endOffset!==3||boundary.startContainer!==text||boundary.endContainer!==text||boundary.startOffset!==2||boundary.endOffset!==2||gap.startContainer!==parent||gap.endContainer!==parent||gap.startOffset!==2||gap.endOffset!==3)throw 'parented split Range movement and parent gap';var detached=document.createTextNode('abcdef'),range=document.createRange();range.setStart(detached,4);range.setEnd(detached,6);var rest=detached.splitText(2);if(range.startContainer!==detached||range.endContainer!==detached||range.startOffset!==2||range.endOffset!==2||rest.data!=='cdef')throw 'detached split does not move Range to new node';var unicode=document.createTextNode('A\ud83d\ude00B');parent.appendChild(unicode);var r=document.createRange();r.setStart(unicode,2);r.setEnd(unicode,4);var low=unicode.splitText(2);if(unicode.data!=='A\ud83d'||low.data!=='\ude00B'||r.startContainer!==unicode||r.startOffset!==2||r.endContainer!==low||r.endOffset!==2||unicode.wholeText!=='A\ud83d\ude00B')throw 'UTF16 split units and Range offsets';"#);
}
#[test]
fn text_split_unsigned_conversion_current_data_typed_bounds_and_author_effects(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var text=document.createTextNode('old'),calls=0,tail=text.splitText({valueOf:function(){calls++;text.data='A\ud800B';return 1.9;}});if(calls!==1||text.data!=='A'||tail.data!=='\ud800B')throw 'current data after numeric conversion';var wrapped=document.createTextNode('abcd'),rest=wrapped.splitText(4294967297.9);if(wrapped.data!=='a'||rest.data!=='bcd')throw 'unsigned-long wrap';var nonfinite=document.createTextNode('held'),all=nonfinite.splitText(Infinity);if(nonfinite.data!==''||all.data!=='held')throw 'nonfinite offset becomes zero';var changed=document.createTextNode('old'),watch=new MutationObserver(function(){});watch.observe(changed,{characterData:true});var caught=false;try{changed.splitText({valueOf:function(){changed.data='new';return 99;}});}catch(e){caught=e instanceof DOMException&&e.name==='IndexSizeError'&&e.code===1;}if(!caught||changed.data!=='new'||watch.takeRecords().length!==1)throw 'typed bounds preserve author mutation';for(var bad of [Symbol('offset'),BigInt(1)]){var caught=false;try{changed.splitText(bad);}catch(e){caught=e instanceof TypeError;}if(!caught||changed.data!=='new')throw 'ToNumber failure';}var caught=false;try{changed.splitText();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'required offset argument';"#);
}
#[test]
fn text_split_saved_child_method_origin_precedes_offset_conversion_and_allocation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Text.prototype.splitText,text=document.createTextNode('held'),calls=0,offset={valueOf:function(){calls++;return 1;}},tail=saved.call(text,offset);if(text.data!=='h'||tail.data!=='eld'||tail.ownerDocument!==document||calls!==1)throw 'genuine captured Text split';");page.set_location(&crate::navigation::address("https://other-text-split.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(text,offset);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==1||text.data!=='h'||tail.data!=='eld')throw 'origin before offset conversion and native creation';");
}
